    @EventHandler( payloadType=CreateContractEvent.class )
    public void handle( CreateContractEvent event) {
	    LOGGER.info("handling CreateContractEvent - " + event );
	    Contract entity = new Contract();
            entity.setContractId( event.getContractId() );
            entity.setContractNumber( event.getContractNumber() );
            entity.setStartDate( event.getStartDate() );
            entity.setEndDate( event.getEndDate() );
            entity.setRenewalTermMonths( event.getRenewalTermMonths() );
            entity.setAutoRenew( event.getAutoRenew() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllContract( entity );
    }

