    /**
     * Method to retrieve the Contract via an ContractPrimaryKey.
     * @param 	id Long
     * @return 	Contract
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Contract handle( FindContractQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getContractId() );
    }
    
    /**
     * Method to retrieve a collection of all Contracts
     *
     * @param	query	FindAllContractQuery 
     * @return 	List<Contract> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Contract> handle( FindAllContractQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindContract,
 * but only if the id matches
 *
 * @param		entity	Contract
 */
	protected void emitFindContract( Contract entity ) {
		LOGGER.info("handling emitFindContract" );
		
	    queryUpdateEmitter.emit(FindContractQuery.class,
	                            query -> query.getFilter().getContractId().equals(entity.getContractId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllContract
	 * 
	 * @param		entity	Contract
	 */
	protected void emitFindAllContract( Contract entity ) {
		LOGGER.info("handling emitFindAllContract" );
		
	    queryUpdateEmitter.emit(FindAllContractQuery.class,
	                            query -> true,
	                            entity);
	}

